#!/usr/bin/env python3
"""Validate metadata and local Markdown links; build static catalogue views.

Standard library only. Reads repository files, writes two generated views.
--check writes nothing and fails if the generated files are stale.
"""
import argparse
from datetime import date
from html import escape
import json
from pathlib import Path
import re
import sys
from urllib.parse import unquote, urlsplit

ROOT = Path(__file__).resolve().parents[1]
REPO = 'https://github.com/tanyaskywood/tata-skywood-skills'


def require(condition, message):
    if not condition:
        raise ValueError(message)


def load_skills():
    data = json.loads((ROOT / 'catalogue.json').read_text())
    require(data['schema_version'] == 1, 'Unsupported catalogue schema')
    skills = data['skills']
    require(isinstance(skills, list) and skills, 'Catalogue must contain skills')
    seen = set()
    for s in skills:
        for key in ('id', 'name', 'category', 'summary', 'version', 'status', 'reviewed', 'start_prompt'):
            require(isinstance(s.get(key), str) and s[key].strip(), f'Missing string: {key}')
            require('\n' not in s[key] and '|' not in s[key], f'Invalid table text: {key}')
        slug = s['id']
        require(re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*', slug) and len(slug) <= 64, f'Invalid id: {slug}')
        require(slug not in seen, f'Duplicate id: {slug}')
        seen.add(slug)
        require(re.fullmatch(r'\d+\.\d+\.\d+', s['version']), f'Invalid version: {slug}')
        require(s['status'] in {'experimental', 'field-tested', 'deprecated'}, f'Invalid status: {slug}')
        require(date.fromisoformat(s['reviewed']).isoformat() == s['reviewed'], f'Invalid date: {slug}')
        for key in ('tags', 'inputs', 'outputs'):
            require(isinstance(s.get(key), list) and s[key] and all(isinstance(x, str) and x.strip() for x in s[key]), f'Invalid {key}: {slug}')
        folder = ROOT / 'skills' / slug
        require((folder / 'README.md').is_file(), f'Missing overview: {slug}')
        text = (folder / 'SKILL.md').read_text()
        front = re.match(r'\A---\n(.*?)\n---\n', text, re.S)
        require(front is not None, f'Missing frontmatter: {slug}')
        name = re.search(r'^name: (.+)$', front[1], re.M)
        description = re.search(r'^description: (.+)$', front[1], re.M)
        require(name is not None and name[1].strip('"\'') == slug, f'Name mismatch: {slug}')
        require(description is not None and 0 < len(description[1]) <= 1024, f'Invalid description: {slug}')
    folders = {p.parent.name for p in (ROOT / 'skills').glob('*/SKILL.md')}
    require(seen == folders, 'Catalogue and installed skill folders do not match')
    return sorted(skills, key=lambda s: s['name'].casefold())


def render(skills):
    md = ['# Skill catalogue', '', '<!-- Generated by scripts/catalogue.py; edit catalogue.json. -->', '',
          '[Library](README.md) · [Visual catalogue](https://tanyaskywood.github.io/tata-skywood-skills/) · [Contribute](CONTRIBUTING.md)', '',
          'Browse by category below, or use the visual catalogue to search and sort.', '']
    categories = sorted({s['category'] for s in skills})
    for category in categories:
        md += [f'## {category}', '', '| Skill | Outcome | Version | Status | Reviewed |', '| --- | --- | --- | --- | --- |']
        for s in skills:
            if s['category'] == category:
                md.append(f"| [{s['name']}](skills/{s['id']}/README.md) | {s['summary']} | {s['version']} | {s['status']} | {s['reviewed']} |")
        md.append('')
    md += ['Experimental is a maturity label, not a quality guarantee. Review dates record package review, not proof of customer outcomes.', '']
    cards = []
    for s in skills:
        h = {k: escape(v, quote=True) for k,v in s.items() if isinstance(v, str)}
        search = escape(' '.join([s['name'], s['summary'], s['category'], *s['tags']]).casefold(), quote=True)
        url = f"{REPO}/blob/main/skills/{s['id']}"
        tags = ''.join(f'<span class="tag">{escape(t)}</span>' for t in s['tags'])
        outputs = ''.join(f'<li>{escape(t)}</li>' for t in s['outputs'])
        cards.append(f'''<article class="card" data-name="{h['name']}" data-category="{h['category']}" data-reviewed="{h['reviewed']}" data-search="{search}">
<div><span class="badge">{h['category']}</span></div><h2>{h['name']}</h2>
<div class="meta">v{h['version']} · {h['status']} · Reviewed {h['reviewed']}</div><p>{h['summary']}</p>
<div class="tags">{tags}</div><h3>What you get</h3><ul>{outputs}</ul>
<div class="actions"><a class="primary" href="{url}/README.md">Explore skill ↗</a><a href="{url}/SKILL.md">Read instructions</a></div></article>''')
    html = (ROOT / 'docs/catalogue-template.html').read_text()
    for marker, value in {'<!-- CARDS -->': '\n'.join(cards), '<!-- CATEGORIES -->': ''.join(f'<option>{escape(c)}</option>' for c in categories), '<!-- COUNT -->': str(len(skills))}.items():
        require(html.count(marker) == 1, f'Missing or repeated template marker: {marker}')
        html = html.replace(marker, value)
    return {ROOT / 'CATALOGUE.md': '\n'.join(md), ROOT / 'docs/index.html': html}


def check_links(outputs):
    markdown = {p: p.read_text() for p in ROOT.rglob('*.md') if '.git' not in p.parts}
    markdown.update({p: text for p, text in outputs.items() if p.suffix == '.md'})
    for path, text in markdown.items():
        # Inline Markdown links; remote URLs and section anchors are not fetched.
        for target in re.findall(r'\]\(([^\s)]+)\)', text):
            parts = urlsplit(target)
            if parts.scheme or parts.netloc or not parts.path:
                continue
            dest = (path.parent / unquote(parts.path)).resolve()
            require(dest.is_relative_to(ROOT), f'Link escapes repository: {path.name}: {target}')
            require(dest.exists() or dest in outputs, f'Broken link: {path.relative_to(ROOT)}: {target}')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='Validate without writing; fail for stale generated files')
    args = parser.parse_args()
    skills = load_skills()
    outputs = render(skills)
    check_links(outputs)
    for path, text in outputs.items():
        if args.check:
            require(path.exists() and path.read_text() == text, f'Stale generated file: {path.relative_to(ROOT)}; run python3 scripts/catalogue.py')
        else:
            path.write_text(text)
    print(f"{'Validated' if args.check else 'Generated'} catalogue: {len(skills)} skill(s); metadata and local Markdown links passed.")


if __name__ == '__main__':
    try:
        main()
    except (ValueError, KeyError, OSError, TypeError) as error:
        print(f'Catalogue error: {error}', file=sys.stderr)
        sys.exit(1)
